import { evaluateToyFilesystemWithBlockDeviceAbstrac } from "../src/toy-filesystem-with-block-device-abstrac.mjs";

test("toy-filesystem-with-block-device-abstrac: accepts a clean input with evidence", () => {
	const result = evaluateToyFilesystemWithBlockDeviceAbstrac({ id: "subject-1", occurredAt: "2026-01-01T00:00:00.000Z", quantity: 1 });
	assert.equal(result.status, "accepted");
	assert.ok(result.findings.length > 0);
	assert.ok(result.findings.every((finding) => finding.evidence.length > 0));
});

test("toy-filesystem-with-block-device-abstrac: blocks negative quantity with a critical finding", () => {
	const result = evaluateToyFilesystemWithBlockDeviceAbstrac({ id: "subject-2", occurredAt: "2026-01-01T00:00:00.000Z", quantity: -1 });
	assert.equal(result.status, "blocked");
	assert.ok(result.findings.some((finding) => finding.severity === "critical"));
});
